const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function protocol(url){const socket=new WebSocket(url),requests=new Map();let id=0;socket.addEventListener('message',event=>{const message=JSON.parse(event.data);if(message.method==='Runtime.exceptionThrown')console.error(JSON.stringify(message.params));const request=requests.get(message.id);if(request){requests.delete(message.id);message.error?request.reject(Error(JSON.stringify(message.error))):request.resolve(message.result);}});await new Promise((resolve,reject)=>{socket.addEventListener('open',resolve,{once:true});socket.addEventListener('error',reject,{once:true});});return{socket,send(method,params={}){return new Promise((resolve,reject)=>{const requestId=++id,timer=setTimeout(()=>reject(Error('Chromium timeout: '+method)),5000);requests.set(requestId,{resolve:value=>{clearTimeout(timer);resolve(value);},reject:error=>{clearTimeout(timer);reject(error);}});socket.send(JSON.stringify({id:requestId,method,params}));});}};}
